  const byId = new Map(decorated.map((comment) => [comment.id, comment]));
  const repliesBy = new Map<string, CommentWithAuthor[]>();
  const roots: CommentWithAuthor[] = [];

  for (const comment of decorated) {
    const rootId = threadRootId(comment, byId);
    if (rootId === comment.id) {
      roots.push(comment);
      continue;
    }
    const bucket = repliesBy.get(rootId) ?? [];
    bucket.push(comment);
    repliesBy.set(rootId, bucket);
  }

  return roots.map((comment) => ({
    comment: presentComment(comment),
    replies: (repliesBy.get(comment.id) ?? []).map(presentComment),
  }));
}

function threadRootId(
  comment: CommentWithAuthor,
  byId: ReadonlyMap<string, CommentWithAuthor>,
): string {
  let current = comment;
  const seen = new Set<string>();
  while (current.parentId !== null && !seen.has(current.id)) {
    seen.add(current.id);
    const parent = byId.get(current.parentId);
    if (parent === undefined) return current.id;
    current = parent;
  }
  return current.id;
}

function presentComment(comment: CommentWithAuthor): CommentWithAuthor {
  if (comment.archivedAt === null) return comment;
  return { ...comment, body: "" };
}

