        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

input.new_string:
subscribe("comment.created", async (payload) => {
  const issue = await issueRepo.findIssueById(payload.orgId, payload.issueId);
  const comment = await commentRepo.findCommentById(
    payload.orgId,
    payload.commentId,
  );
  const parent =
    comment?.parentId == null
      ? null
      : await commentRepo.findCommentById(payload.orgId, comment.parentId);

  const mentioned = new Set(payload.mentionedUserIds);
  const watchers: UserId[] = [];
  const seen = new Set<UserId>();
  for (const id of [
    issue?.authorId,
    issue?.assigneeId,
    parent?.authorId,
  ]) {
    if (id == null || seen.has(id) || mentioned.has(id)) continue;
    seen.add(id);
    watchers.push(id);
  }

  await notify(payload.orgId, "comment_created", watchers, {
    title: "New comment",
    body: `A comment was added to issue ${payload.issueId}`,
    href: `/issues/${payload.issueId}`,
    actorId: payload.actorId,
  });

  if (payload.mentionedUserIds.length > 0) {
    await notify(
      payload.orgId,
      "comment_mention",
      payload.mentionedUserIds,
      {
        title: "You were mentioned",
        body: `You were mentioned on issue ${payload.issueId}`,
        href: `/issues/${payload.issueId}`,
        actorId: payload.actorId,
      },
    );
  }
});

subscribe("comment.updated", async (payload) => {
  if (payload.mentionedUserIds.length === 0) return;
  await notify(
    payload.orgId,
    "comment_mention",
    payload.mentionedUserIds,
    {
      title: "You were mentioned",
      body: `You were mentioned on issue ${payload.issueId}`,
      href: `/issues/${payload.issueId}`,
      actorId: payload.actorId,
    },
  );
});

